import {JumpGames} from './jump-games.js';
import {Abedemu} from './abedemu.js';
import {Sulia} from './sulia.js';
import {footballVariant} from './football-variants.js';
import {Pampanaa,RubberBand} from './neighbourhood-games.js';
import {Mode} from './mode-base.js';
import {traditional} from './traditional.js';
import {Football} from './football.js';
import {THREE,box,cylinder,sphere,ball,ring,moveActor,distance,palette} from './world.js';
import {createBoardMode} from './board-modes.js';
import {createMotionMode} from './motion-modes.js';
export function createMode(ctx){if(['highjump','agawowa'].includes(ctx.game.id))return new JumpGames(ctx);if(ctx.game.id==='abedemu')return new Abedemu(ctx);if(ctx.game.id==='sulia')return new Sulia(ctx);const variant=footballVariant(ctx);if(variant)return variant;if(['pampanaa','shooting'].includes(ctx.game.id))return new Pampanaa(ctx);if(ctx.game.id==='rubberband')return new RubberBand(ctx);const revised=traditional(ctx);if(revised)return revised;const id=ctx.game.id;if(['oware','ludo','dame','counters'].includes(id))return createBoardMode(ctx);if(id==='football')return new Football(ctx);if(['pilolo','pampanaa','shooting','sansankroma','police','pretend','tyre'].includes(id))return new Explore(ctx);return createMotionMode(ctx);}
class Explore extends Mode{
 constructor(ctx){super(ctx);this.id=ctx.game.id;this.world.setCamera('chase');this.you=this.player(0,7);this.world.follow?.(this.you);this.home=this.circle(0,7,1.3);this.text('HOME',0,.2,7,'#ffe2a1',.4);this.lives=3;this.boost=0;this.carry=null;this.invuln=0;this.items=[];this.rivals=[];this.obstacles=[];this.limit=this.id==='pretend'?Infinity:75;this.setActions([{id:'interact',label:['pampanaa','shooting'].includes(this.id)?'Tag':this.id==='tyre'?'Push':'Pick / use',key:'Space'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);
 for(const [x,z]of (this.id==='tyre'?[[-2,-5],[2,-1],[-2,4]]:[[-8,-5],[-3,-7],[7,-5],[9,2],[-8,2],[4,2]])){const crate=box(1.4,1.5,1.4,0x79644a,x,.75,z,this.root);box(1.5,.12,1.5,0x927b58,x,1.55,z,this.root);this.obstacles.push({x,z,r:1});}
 if(this.id==='pilolo'){for(let i=0;i<5;i++){const [x,z]=[[-10,-4],[-4,-8],[9,-7],[10,3],[-10,4]][i];const stick=cylinder(.065,.08,.9,0xf3cd78,x,.4,z,this.root,6);stick.rotation.z=.5;stick.userData.pick=i;this.items.push(stick);}this.note('Find a stick, pick it up, then return HOME.');}
 if(['pampanaa','shooting'].includes(this.id)){for(let i=0;i<5;i++){const a=this.player([-8,-4,7,10,-10][i],[-6,-8,-6,2,3][i],0x3d8f7e);a.userData.tagged=false;this.rivals.push(a);}this.note('Walk around the crates. Face a rival and call Tag within 5 steps.');}
 if(this.id==='sansankroma'){this.refuges=[[-10,-7],[10,-7],[10,7],[-10,7]];this.refuges.forEach(([x,z],i)=>{this.circle(x,z,1.3,i===0?palette.gold:0xe3d5ac);this.text(String(i+1),x,.3,z,'#fff0bd',.5);});this.hawk=this.player(0,-6,0x3e705b);this.next=0;this.note('Reach refuge 1. The hawk is on your heels!');}
 if(this.id==='police'){this.circle(8,-6,2,0x6dc5b5);for(let i=0;i<3;i++){const p=this.player(7+i,-6,0xe1bc52);this.items.push(p);}this.hawk=this.player(-5,-3,0x3c7798);this.note('Go to the blue circle and rescue one friend at a time.');}
 if(this.id==='pretend'){this.tasks=[{name:'BASKET',x:-9,z:-4,to:{x:8,z:6}},{name:'WATER',x:8,z:-5,to:{x:-8,z:5}},{name:'MEAL',x:0,z:-7,to:{x:0,z:7}}];this.tasks.forEach((q,i)=>{const item=cylinder(i===1?.38:.5,.35,.55,[0xc59d57,0x577e91,0xc15e39][i],q.x,.4,q.z,this.root);this.items.push(item);this.circle(q.to.x,q.to.z,1.2);this.text(q.name,q.x,1.4,q.z,'#ffe7a6',.35);});this.note('Bring the basket to the yellow circle on the right.');}
 if(this.id==='tyre'){this.you.visible=true;this.tyre=new THREE.Mesh(new THREE.TorusGeometry(.7,.16,10,24),new THREE.MeshStandardMaterial({color:0x292c28,roughness:.95}));this.tyre.position.set(0,.8,7);this.root.add(this.tyre);this.you.position.set(0,0,7);this.gates=[[0,4],[-2.5,1],[0,-3],[2.5,-6],[0,-8],[-2.5,-6],[0,1],[2.5,7]];this.gateMeshes=this.gates.map(([x,z],i)=>{const g=ring(1.2,i===0?palette.gold:0xe2d2ad,x,z,this.root,.08);this.text(String(i+1),x,.2,z,'#ffe9b7',.45);return g;});this.pushStick=cylinder(.025,.035,1.5,0x93805e,0,.8,7,this.root,8);this.tyreSpin=0;this.note('Push the tyre through the gates. Keep the wheel ahead of your stick.');}}
 action(id){if(id!=='interact'||this.done)return;const p=this.you.position;if(this.id==='tyre'){this.boost=1;this.note('Push! Keep the tyre clear of the crates.');this.ui.sound('swing');}if(this.id==='pilolo'){if(this.carry){if(distance(p,{x:0,z:7})<1.8){this.carry.visible=false;this.carry=null;this.score++;this.note(`${this.score} / 5 sticks home. Find the next one.`);this.ui.sound('point');}}else{const stick=this.items.find(m=>m.visible&&distance(m,this.you)<1.7);if(stick){this.carry=stick;this.note('Got one! Bring it HOME.');}else this.note('Move closer to a glowing stick.');}}
 if(['pampanaa','shooting'].includes(this.id)){const dir=new THREE.Vector3(Math.sin(this.you.rotation.y),0,Math.cos(this.you.rotation.y));const target=this.rivals.find(a=>{const v=a.position.clone().sub(p);const d=v.length();const facing=v.normalize().dot(dir)>.35;const blocked=this.obstacles.some(o=>{const dx=a.position.x-p.x,dz=a.position.z-p.z,t=THREE.MathUtils.clamp(((o.x-p.x)*dx+(o.z-p.z)*dz)/(d*d||1),0,1);return Math.hypot(p.x+dx*t-o.x,p.z+dz*t-o.z)<o.r;});return !a.userData.tagged&&d<5&&facing&&!blocked;});if(target){target.userData.tagged=true;target.userData.pose='cheer';this.score++;this.note('Tagged! '+this.score+' of 5.');this.ui.sound('point');}else this.note('Face a rival nearby, with a clear view.');}
 if(this.id==='police'){if(this.carry&&distance(p,{x:0,z:7})<1.6){this.carry.position.set(-2+this.score,0,8);this.carry.userData.safe=true;this.carry=null;this.score++;this.ui.sound('point');this.note('Friend safe! Go back for the others.');}else if(!this.carry){const friend=this.items.find(m=>!m.userData.safe&&distance(m,this.you)<2);if(friend){this.carry=friend;this.note('They are following. Get HOME!');}}}
 if(this.id==='pretend'){const task=this.tasks[this.score];if(!task)return;if(this.carry&&distance(p,task.to)<1.7){this.carry.position.set(task.to.x,.3,task.to.z);this.carry=null;this.score++;this.ui.sound('point');this.note(this.score<3?'Next: bring '+this.tasks[this.score].name+' to its circle.':'Everyone is looked after!');}else if(!this.carry&&distance(p,task)<1.7){this.carry=this.items[this.score];this.note('Carry '+task.name+' to its yellow circle.');}}
 }
 hit({point}){this.input.target=point;}
 update(dt,t){this.invuln=Math.max(0,this.invuln-dt);const old=this.you.position.clone();this.boost=Math.max(0,this.boost-dt);this.move(this.you,dt,this.boost>0?9:this.input.sprint?8:5.5,this.id==='tyre'?4:12);for(const o of this.obstacles){if(distance(this.you,o)<o.r+.35){this.you.position.copy(old);if(this.id==='tyre'&&this.invuln===0){this.lives--;this.invuln=1;this.note('Bumped a crate! Steer around it.');}}}if(this.carry){if(this.id==='police'){this.carry.userData.run=moveActor(this.carry,{x:this.you.position.x-.8,z:this.you.position.z+.6},6,dt);}else this.carry.position.set(this.you.position.x,this.id==='pretend'?1.4:1.2,this.you.position.z+.4);}
 if(this.hawk){const safe=this.id==='sansankroma'&&this.refuges.some(([x,z])=>distance(this.you,{x,z})<1.2);this.hawk.userData.run=moveActor(this.hawk,this.you.position,safe?0:3.1+(this.score*.12),dt);if(!safe&&distance(this.hawk,this.you)<.8&&this.invuln===0){this.lives--;this.invuln=2;this.hawk.position.set(0,0,-7);this.note('Tagged! '+this.lives+' chances left.');}if(this.id==='sansankroma'){const q=this.refuges[this.next];if(distance(this.you,{x:q[0],z:q[1]})<1.2){this.score++;this.next=(this.next+1)%4;this.note('Safe! Now reach refuge '+(this.next+1)+'.');this.ui.sound('point');}}}
 if(['pampanaa','shooting'].includes(this.id)){for(let i=0;i<this.rivals.length;i++){const rival=this.rivals[i];if(rival.userData.tagged)continue;const origin={x:[-8,-4,7,10,-10][i],z:[-6,-8,-6,2,3][i]},patrol={x:origin.x+Math.sin(t*.35+i)*1.8,z:origin.z+Math.cos(t*.3+i)*1.1};rival.userData.run=moveActor(rival,patrol,1.2,dt);const to=this.you.position.clone().sub(rival.position),dist=to.length(),view=to.clone().normalize().dot(new THREE.Vector3(Math.sin(rival.rotation.y),0,Math.cos(rival.rotation.y)));const occluded=this.obstacles.some(o=>{const k=THREE.MathUtils.clamp(((o.x-rival.position.x)*to.x+(o.z-rival.position.z)*to.z)/(dist*dist||1),0,1);return Math.hypot(rival.position.x+to.x*k-o.x,rival.position.z+to.z*k-o.z)<o.r;});if(dist<4.5&&view>.7&&!occluded&&this.invuln===0){this.lives--;this.invuln=3;this.note('They spotted you first! Keep your distance.');}}}
 if(this.id==='tyre'){const travel=distance(this.you,old);this.tyreSpin+=travel/.7;const heading=this.you.rotation.y;this.tyre.position.set(this.you.position.x+Math.sin(heading)*.9,.8,this.you.position.z+Math.cos(heading)*.9);this.tyre.rotation.set(0,heading+Math.PI/2,this.tyreSpin);this.pushStick.position.set(this.you.position.x+Math.sin(heading)*.55,.8,this.you.position.z+Math.cos(heading)*.55);this.pushStick.rotation.set(Math.PI/3,heading,0);this.you.userData.pose=this.you.userData.run?'point':'idle';const q=this.gates[this.score];if(q&&distance(this.you,{x:q[0],z:q[1]})<1.3){this.gateMeshes[this.score].material.color.set(0x5cba77);this.score++;this.ui.sound('point');this.note('Gate '+this.score+' cleared!');}}
 this.you.visible=this.invuln<=0||Math.floor(t*8)%2===0;const goal={pilolo:5,pampanaa:5,shooting:5,sansankroma:8,police:3,pretend:3,tyre:8}[this.id];this.status(`${this.score} / ${goal}`,this.id==='pretend'?'COMPOUND TASKS':`${Math.ceil(Math.max(0,this.limit-this.time))}s · ${this.lives} CHANCES`);if(this.score>=goal)this.finish(this.id==='pretend'?'EVERYONE IS HAPPY':'YOU DID IT!',this.id==='pretend'?'The compound is ready. Play another story.':`${goal} challenges completed.`);else if(this.lives<=0||this.time>=this.limit)this.finish(this.lives<=0?'CAUGHT THIS TIME':'TIME UP',`${this.score} of ${goal} completed. Another round?`,false);}
}
